# each bag's 1 kg twin carries the same texts (CLAUDE.md 8a)
PRODUCTS = {636: ['MG006117', 'MG006067', 'MG006077'], 639: ['011217', '006487']}
here = os.path.dirname(os.path.abspath(__file__))
for pid, skus in PRODUCTS.items():
    for lang in ('ru', 'hy'):
        variants = {}
        for sku in skus:
            body = {'ingredient_information': ING[sku][lang],
                    'feeding_instructions': FEED[FEED_OF[sku]][lang]}
            variants[sku] = body
            variants[sku + '-KG'] = dict(body)
        json.dump({'variants': variants},
                  open(os.path.join(here, f'{pid}-{lang}.json'), 'w'),
                  ensure_ascii=False, indent=1)
        print(f'{pid}-{lang}.json: {len(variants)} variants')
